function voxelTree(x,z,scale=1){const g=new THREE.Group();g.position.set(x,0,z);const trunk=box(g,0,.62*scale,0,.42*scale,1.25*scale,.42*scale,0x76513b);const colors=[biome.tree,biome.tree,biome.accent];for(let i=0;i<3;i++){let b=box(g,0,(1.35+i*.48)*scale,0,(2.25-i*.34)*scale,.9*scale,(2.25-i*.34)*scale,colors[i]);b.position.x=(i%2?.18:-.12)*scale}scene.add(g);decor.push(g);return g}
function makeFlower(x,z){const g=new THREE.Group();g.position.set(x,.03,z);box(g,0,.14,0,.09,.28,.09,0x47754f);const f=box(g,0,.3,0,.2,.16,.2,biome.flower);scene.add(g);decor.push(g)}
function makeRock(x,z,s=1,color=0x878d78){const r=box(scene,x,s*.28,z,s*.85,s*.56,s*.72,color);r.rotation.y=worldRand()*2;decor.push(r)}
function buildWorld(){worldRand=rng(seed);biome=biomes[Math.floor(worldRand()*biomes.length)];scene.background=new THREE.Color(0x9ac4bc);scene.fog=new THREE.Fog(0x9ac4bc,34,105);const hemi=new THREE.HemisphereLight(0xe4f0dc,0x49584b,2.1);scene.add(hemi);const sun=new THREE.DirectionalLight(0xffedc4,2.7);sun.position.set(-28,42,18);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-38;sun.shadow.camera.right=38;sun.shadow.camera.top=38;sun.shadow.camera.bottom=-38;scene.add(sun);scene.userData.sun=sun;
const geo=new THREE.PlaneGeometry(180,180,90,90);geo.rotateX(-Math.PI/2);const p=geo.attributes.position;for(let i=0;i<p.count;i++){const x=p.getX(i),z=p.getZ(i);let h=Math.sin(x*.075+1.4)*1.25+Math.cos(z*.095)*.9+Math.sin((x+z)*.045)*1.7;h+=Math.max(0,Math.sin(x*.18+z*.13)-.75)*1.8;p.setY(i,h)}geo.computeVertexNormals();ground=new THREE.Mesh(geo,new THREE.MeshStandardMaterial({color:biome.ground,roughness:1,flatShading:true}));ground.receiveShadow=true;scene.add(ground);
const water=new THREE.Mesh(new THREE.PlaneGeometry(32,26),new THREE.MeshStandardMaterial({color:0x5b9c9b,transparent:true,opacity:.78,roughness:.27,metalness:.1}));water.rotation.x=-Math.PI/2;water.position.set(-26,-.5,-25);scene.add(water);for(let i=0;i<210;i++){let x=(worldRand()-.5)*95,z=(worldRand()-.5)*95;if(Math.hypot(x,z)<8||x<-11&&x>-42&&z<-12&&z>-39)continue;let scale=.7+worldRand()*.85;if(worldRand()<.67)voxelTree(x,z,scale);else if(worldRand()<.65)makeRock(x,z,.7+worldRand(),0x798276);else makeFlower(x,z)}
// A welcoming hamlet of timber, stone and canvas.
for(let n=0;n<4;n++){const x=8+(n%2)*5,z=-5+Math.floor(n/2)*5;box(scene,x,.65,z,3.8,1.3,3.5,0x9a7850);box(scene,x,1.75,z,4.2,.35,4,0x664a38);const roof=box(scene,x,2.35,z,4.3,.55,4.25,n%2?0x9b6248:0x76634b);roof.rotation.z=.08;box(scene,x,1,z+1.78,.65,1.6,.12,0x3e4035);for(let q=-1;q<=1;q+=2)box(scene,x+q*1.72,.8,z,.12,1.6,.12,0x72583d)}
// A stone ring, standing stones, and a distant watchtower.
for(let i=0;i<8;i++){const a=i*Math.PI/4;box(scene,17+Math.cos(a)*3,.8,-1+Math.sin(a)*3,.7,1.6,.65,0x877b68).rotation.y=-a}for(let i=0;i<3;i++)box(scene,-16+i*1.2,1,-7, .55,2,.5,0x9c9881);
const tower=new THREE.Group();tower.position.set(-23,0,13);for(let y=0;y<5;y++)box(tower,0,.8+y*1.2,0,2.8,.85,2.8,y%2?0x807769:0x928775);box(tower,0,6.1,0,3.7,.7,3.7,0x705349);scene.add(tower);
}
function makeHero(){const g=new THREE.Group();const c=hero.class;const tunic={Warrior:0x526c7c,Ranger:0x4d755a,Mage:0x665689,Rogue:0x7b554e}[c];const skin={Hearthkin:0xd9ae85,Glimmerfolk:0xc9d2a3,Stoneborn:0x9e8d79}[hero.race];box(g,0,1.02,0,.72,.82,.42,tunic);box(g,0,1.67,0,.58,.54,.56,skin);box(g,0,2,0,.65,.16,.62,hero.hair||0x4c392e);box(g,-.14,1.68,.29,.07,.07,.05,0x27342e);box(g,.14,1.68,.29,.07,.07,.05,0x27342e);box(g,-.22,.42,0,.27,.54,.3,0x4b4a43);box(g,.22,.42,0,.27,.54,.3,0x4b4a43);box(g,-.49,1.02,0,.2,.76,.24,tunic);box(g,.49,1.02,0,.2,.76,.24,tunic);box(g,0,.7,.25,.35,.13,.08,0xb98d4f);
if(c==='Warrior'){box(g,.63,.95,.1,.12,.92,.16,0xaab3b0);box(g,.66,1.28,.1,.23,.18,.19,0xd1bb83)}if(c==='Ranger')box(g,.65,1.15,.05,.1,.72,.1,0x866344);if(c==='Mage')box(g,.55,1.14,0,.14,.87,.14,0x8870c6);if(c==='Rogue')box(g,.62,.94,.13,.12,.42,.09,0xc3c6b0);
g.position.set(0,0,0);scene.add(g);return g}
function makeEnemy(x,z,type='imp'){const g=new THREE.Group();const color=type==='mossling'?0x628e68:type==='wolf'?0x887464:0xd47758;const size=type==='wolf'?.72:1;box(g,0,.5,0,.82*size,.85*size,.7*size,color);box(g,0,1.13*size,0,.72*size,.58*size,.68*size,type==='wolf'?0x9b8874:color);box(g,-.17,.54,.37,.09,.1,.05,0xfee497);box(g,.17,.54,.37,.09,.1,.05,0xfee497);if(type==='imp'){box(g,-.34,1.55,0,.22,.55,.24,0x9d5a48).rotation.z=-.42;box(g,.34,1.55,0,.22,.55,.24,0x9d5a48).rotation.z=.42}if(type==='wolf'){box(g,0,1.13,.37,.45,.25,.55,color);box(g,-.2,1.68,0,.12,.3,.12,color);box(g,.2,1.68,0,.12,.3,.12,color)}g.position.set(x,0,z);g.userData={type,hp:type==='wolf'?48:34,max:type==='wolf'?48:34,attack:0,phase:worldRand?worldRand()*6:0};scene.add(g);enemies.push(g);return g}
function spawnEnemies(){const types=['imp','mossling','wolf'];for(let i=0;i<12;i++){let a=worldRand()*Math.PI*2,r=12+worldRand()*37;makeEnemy(Math.cos(a)*r,Math.sin(a)*r,types[Math.floor(worldRand()*types.length)])}for(let i=0;i<6;i++)makeFlower(-20+worldRand()*10,8+worldRand()*8)}
function makeCompanion(){const g=new THREE.Group();box(g,0,.45,0,.8,.68,.78,0xd28f54);box(g,0,.96,0,.72,.55,.68,0xd99f64);box(g,0,1.22,.12,.28,.28,.3,0xf2cf85);for(let s of [-1,1]){box(g,s*.23,1.05,.43,.07,.07,.05,0x34362f);box(g,s*.26,1.4,0,.14,.4,.15,0x9b7653).rotation.z=s*.2}g.position.set(2,0,2);scene.add(g);return g}
function init(){scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,230);camera.position.set(0,7,10);renderer=new THREE.WebGLRenderer({antialias:false,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.6));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;game.appendChild(renderer.domElement);clock3=new THREE.Clock();buildWorld();player=makeHero();spawnEnemies();player.position.set(0,0,0);scene.add(new THREE.AmbientLight(0xffffff,.16));window.addEventListener('resize',resize);animate()}

