function say(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(say.timer);say.timer=setTimeout(()=>t.classList.remove('show'),2100)}function updateHud(){ $('#hpText').textContent=`${Math.ceil(hp)} / ${maxHp}`;$('#hpFill').style.width=`${100*hp/maxHp}%`;$('#xpText').textContent=`${xp} / ${xpNeed}`;$('#xpFill').style.width=`${100*xp/xpNeed}%`;$('#level').textContent=level;$('#heroLabel').textContent=`${hero.name} · ${hero.class}`;$('#gearLabel').textContent=`Wayfarer's kit · Skill points ${skillPoints}`;$('#portrait').textContent={Warrior:'⚔',Ranger:'➶',Mage:'✧',Rogue:'◈'}[hero.class];$('#questProgress').textContent=`Imps sent home · ${Math.min(questCount,3)} / 3`}
function gainXP(n){xp+=n;while(xp>=xpNeed){xp-=xpNeed;level++;skillPoints++;xpNeed=Math.round(xpNeed*1.22);maxHp+=8;hp=maxHp;say(`Level ${level}! +1 skill point · vitality restored`)}updateHud()}
function nearestEnemy(range=4.2){let best=null,d=range;for(const e of enemies){if(!e.visible||e.userData.hp<=0)continue;const n=e.position.distanceTo(player.position);if(n<d){best=e;d=n}}return best}
function hit(e,amount){if(!e||!e.visible)return;e.userData.hp-=amount;e.scale.set(1.13,.9,1.13);setTimeout(()=>{if(e.visible)e.scale.set(1,1,1)},100);if(e.userData.hp<=0){e.visible=false;kills++;inventory['Fieldstone']=(inventory['Fieldstone']||0)+1;inventory['Pinewood']=(inventory['Pinewood']||0)+1;if(e.userData.type==='imp'){questCount++;if(questCount===3){say('Rumor complete! The baker sends thanks.');inventory.Sunberry+=3;gainXP(55)}}gainXP(e.userData.type==='wolf'?42:32);if(Math.random()<.35){berries++;inventory.Sunberry=(inventory.Sunberry||0)+1}updateHud()}}
function attack(){if(attackCd>0)return;attackCd=.42;const e=nearestEnemy(hero.class==='Ranger'?5:3.3);const power={Warrior:24,Ranger:21,Mage:25,Rogue:18}[hero.class]+level*3;if(e){hit(e,power);say({Warrior:'Steel rings through the glade!',Ranger:'A true shot!',Mage:'A spark finds its mark!',Rogue:'Quick as a whisper.'}[hero.class])}else say('Your strike cuts only air.');player.rotation.y=0;}
function special(){if(skillCd>0)return;skillCd=5.5;const ability=abilities[hero.class];const near=enemies.filter(e=>e.visible&&e.position.distanceTo(player.position)<(hero.class==='Mage'?8:6));if(hero.class==='Rogue'){player.position.x+=Math.sin(player.rotation.y)*3;player.position.z+=Math.cos(player.rotation.y)*3;near.forEach(e=>hit(e,15+level*2))}else if(hero.class==='Ranger'){near.slice(0,3).forEach(e=>hit(e,20+level*2))}else if(hero.class==='Mage'){near.forEach(e=>hit(e,17+level*2))}else near.slice(0,4).forEach(e=>hit(e,25+level*2));say(`${ability}!`)}
function dodge(){if(invuln>0)return;invuln=.7;const v=moveVector();if(v.length()<.1)v.set(Math.sin(player.rotation.y),0,Math.cos(player.rotation.y));player.position.add(v.normalize().multiplyScalar(3.4));say('Quickstep!')}
